(174, 'rankingcoach_loaded_modules', 'a:2:{s:8:\"checksum\";s:32:\"2fb16ecb8cb416195fa59b0936d824a9\";s:7:\"modules\";a:36:{i:0;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:21:\"rankingcoachDashboard\";s:5:\"title\";s:22:\"rankingCoach Dashboard\";s:11:\"description\";s:170:\"The central module that coordinates and manages all other Ranking Coach modules. Provides the main interface and reporting dashboard for SEO analysis and recommendations.\";s:7:\"version\";s:5:\"2.0.0\";s:8:\"settings\";a:1:{i:0;a:4:{s:3:\"key\";s:29:\"dashboard_reporting_frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:100:\"How often SEO reports and summaries are generated on the dashboard: \'daily\', \'weekly\', or \'monthly\'.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:100;s:5:\"class\";s:87:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Core\\RankingCoachDashboard\\RankingCoachDashboard\";}i:1;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:12:\"linkAnalyzer\";s:5:\"title\";s:13:\"Link Analyzer\";s:11:\"description\";s:121:\"Extracts and analyzes links from content, storing detailed information about each link for SEO analysis and optimization.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:22:\"analyze_internal_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:78:\"Extract and analyze internal links (links to other pages within your website).\";}i:1;a:4:{s:3:\"key\";s:22:\"analyze_external_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:78:\"Extract and analyze external links (links to websites outside of your domain).\";}i:2;a:4:{s:3:\"key\";s:22:\"analyze_nofollow_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:56:\"Extract and analyze links with the \'nofollow\' attribute.\";}i:3;a:4:{s:3:\"key\";s:23:\"analyze_sponsored_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:57:\"Extract and analyze links with the \'sponsored\' attribute.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:30;s:5:\"class\";s:70:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Links\\LinkAnalyzer\\LinkAnalyzer\";}i:2;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:11:\"linkCounter\";s:5:\"title\";s:12:\"Link Counter\";s:11:\"description\";s:199:\"Analyzes content to count internal and external links, providing statistics for SEO analysis and content optimization.  Configurable settings determine which types of links are included in the count.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:20:\"count_internal_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:90:\"Include internal links (links to other pages within your website) in the total link count.\";}i:1;a:4:{s:3:\"key\";s:20:\"count_external_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:90:\"Include external links (links to websites outside of your domain) in the total link count.\";}i:2;a:4:{s:3:\"key\";s:20:\"count_nofollow_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:115:\"Include links with the \'nofollow\' attribute in the count. These links are typically not followed by search engines.\";}i:3;a:4:{s:3:\"key\";s:21:\"count_sponsored_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:103:\"Include links with the \'sponsored\' attribute in the count. These links are typically paid or sponsored.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:30;s:5:\"class\";s:68:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Links\\LinkCounter\\LinkCounter\";}i:3;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:11:\"socialMedia\";s:5:\"title\";s:24:\"Social Media Integration\";s:11:\"description\";s:198:\"Enhances social media sharing and visibility by integrating social media meta tags (Open Graph, Twitter Cards, etc.) into pages and posts.  Allows customization of meta data for different platforms.\";s:7:\"version\";s:5:\"1.1.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:18:\"enable_facebook_og\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:98:\"Enable Open Graph meta tags for Facebook and other platforms that use Open Graph (e.g., LinkedIn).\";}i:1;a:4:{s:3:\"key\";s:20:\"enable_twitter_cards\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:62:\"Enable Twitter Card meta tags for enhanced display on Twitter.\";}i:2;a:4:{s:3:\"key\";s:20:\"default_social_image\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:119:\"The default image URL to use for social media shares if no featured image is set.  Leave blank to use the website logo.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:29;s:5:\"class\";s:57:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Social\\SocialMedia\";}i:4;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:14:\"webmasterTools\";s:5:\"title\";s:26:\"Search Console Integration\";s:11:\"description\";s:146:\"Integrates with Google Search Console and Bing Webmaster Tools to verify website ownership and access performance data and diagnostic information.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:24:\"google_verification_code\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:99:\"Your Google Search Console verification code. This code is used to prove ownership of your website.\";}i:1;a:4:{s:3:\"key\";s:22:\"bing_verification_code\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:108:\"Your Bing Webmaster Tools verification code. This code is used to prove ownership of your website with Bing.\";}i:2;a:4:{s:3:\"key\";s:20:\"automatic_submission\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:73:\"Automatically submit updated sitemaps to Google and Bing upon generation.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:28;s:5:\"class\";s:59:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Tools\\WebmasterTools\";}i:5;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:21:\"userEngagementMetrics\";s:5:\"title\";s:31:\"User Engagement Metrics Tracker\";s:11:\"description\";s:265:\"Tracks and analyzes user engagement metrics, such as time on page, scroll depth, bounce rate, and conversion rates, to assess content effectiveness and identify areas for improvement. Integrates with Advanced SEO Analytics for a comprehensive view of user behavior.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:18:\"track_time_on_page\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:108:\"Track the average time users spend on each page, providing insights into content engagement and readability.\";}i:1;a:4:{s:3:\"key\";s:18:\"track_scroll_depth\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:126:\"Track how far users scroll down each page, helping identify content drop-off points and optimize content length and structure.\";}i:2;a:4:{s:3:\"key\";s:17:\"track_bounce_rate\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:153:\"Track the bounce rate (percentage of users who leave after viewing only one page) to identify pages with poor user engagement or unclear calls to action.\";}i:3;a:4:{s:3:\"key\";s:15:\"conversion_goal\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:269:\"Define a conversion goal, such as form submissions, product purchases, or newsletter sign-ups. This allows the module to track conversion rates and assess the effectiveness of your content in driving desired actions. (See documentation for setting up conversion goals).\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:27;s:5:\"class\";s:70:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Analytics\\UserEngagementMetrics\";}i:6;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:8:\"videoSeo\";s:5:\"title\";s:19:\"Video SEO Optimizer\";s:11:\"description\";s:246:\"Enhances video content visibility in search results by generating video sitemaps, adding VideoObject schema markup, and optimizing video metadata (titles, descriptions, tags). Helps improve video rankings and drive more traffic from video search.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:22:\"generate_video_sitemap\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:118:\"Generate a separate sitemap specifically for video content, improving the discoverability of videos by search engines.\";}i:1;a:4:{s:3:\"key\";s:19:\"enable_video_schema\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:239:\"Add VideoObject schema markup to video pages, providing search engines with detailed information about your videos, such as title, description, thumbnail, and duration. This can enhance visibility in video search results and rich snippets.\";}i:2;a:4:{s:3:\"key\";s:27:\"autogenerate_video_metadata\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:170:\"Automatically generate optimized video metadata (title, description, tags) based on video content analysis.  Requires integration with a video hosting/processing service.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:26;s:5:\"class\";s:53:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Media\\VideoSEO\";}i:7;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:23:\"voiceSearchOptimization\";s:5:\"title\";s:25:\"Voice Search Optimization\";s:11:\"description\";s:259:\"Optimizes website content and structure for voice search by focusing on long-tail keywords, conversational language, FAQ schema markup, and mobile-friendliness. Improves visibility in voice search results and enhances user experience for voice search queries.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:17:\"enable_faq_schema\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:151:\"Enable FAQPage schema markup to provide structured data for frequently asked questions, improving visibility in voice search results and rich snippets.\";}i:1;a:4:{s:3:\"key\";s:34:\"conversational_keyword_suggestions\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:145:\"Provide suggestions for conversational and long-tail keywords within the content editor, helping users optimize content for voice search queries.\";}i:2;a:4:{s:3:\"key\";s:25:\"mobile_optimization_check\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:143:\"Perform checks for mobile-friendliness, a crucial factor for voice search optimization, as most voice searches are performed on mobile devices.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:25;s:5:\"class\";s:72:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Technical\\VoiceSearchOptimization\";}i:8;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:20:\"performanceOptimizer\";s:5:\"title\";s:29:\"Website Performance Optimizer\";s:11:\"description\";s:239:\"Optimizes website performance by implementing technical best practices, such as browser caching, GZIP compression, HTML/CSS/JS minification, and database optimization. Improves page load speed, Core Web Vitals, and overall SEO performance.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:22:\"enable_browser_caching\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:132:\"Enable browser caching to store static assets (images, CSS, JS) locally on the user\'s browser, reducing load times on repeat visits.\";}i:1;a:4:{s:3:\"key\";s:23:\"enable_gzip_compression\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:126:\"Enable GZIP compression to reduce the size of HTML, CSS, and JavaScript files sent from the server, improving download speeds.\";}i:2;a:4:{s:3:\"key\";s:18:\"minify_html_css_js\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:143:\"Minify HTML, CSS, and JavaScript files by removing unnecessary characters and whitespace, further reducing file sizes and improving load times.\";}i:3;a:4:{s:3:\"key\";s:25:\"optimize_database_queries\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:204:\"Optimize database queries to improve data retrieval speed. This can have a significant impact on overall website performance, but requires careful configuration. (See documentation for advanced settings).\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:24;s:5:\"class\";s:71:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Performance\\PerformanceOptimizer\";}i:9;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:15:\"backlinkManager\";s:5:\"title\";s:16:\"Backlink Manager\";s:11:\"description\";s:335:\"Tracks and monitors backlinks to your website, analyzing backlink quality, identifying new and lost backlinks, and providing insights into your backlink profile. Helps users improve their link building strategy and understand the impact of backlinks on SEO performance. Integrates with Competitor Analysis to compare backlink profiles.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:24:\"backlink_check_frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:83:\"How often to check for new and lost backlinks: \'weekly\', \'bi-weekly\', or \'monthly\'.\";}i:1;a:4:{s:3:\"key\";s:26:\"notify_on_backlink_changes\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:109:\"Send email notifications to the administrator when new backlinks are acquired or existing backlinks are lost.\";}i:2;a:4:{s:3:\"key\";s:24:\"analyze_backlink_quality\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:156:\"Analyze the quality of backlinks based on factors like domain authority, spam score, and relevance. Helps identify high-quality link building opportunities.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:23;s:5:\"class\";s:60:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Links\\BacklinkManager\";}i:10;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:17:\"advancedAnalytics\";s:5:\"title\";s:22:\"Advanced SEO Analytics\";s:11:\"description\";s:270:\"Integrates with Google Analytics and other analytics platforms to provide in-depth SEO performance data, including organic traffic, bounce rate, user behavior, conversion tracking, and other key metrics. Helps users understand how SEO efforts impact website performance.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:19:\"google_analytics_id\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:115:\"Your Google Analytics tracking ID (e.g., UA-XXXXXXXX-X). Enter this ID to enable integration with Google Analytics.\";}i:1;a:4:{s:3:\"key\";s:26:\"track_user_behavior_events\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:159:\"Track specific user interactions and behavior events, such as scroll depth, link clicks, and form submissions.  Provides more granular data on user engagement.\";}i:2;a:4:{s:3:\"key\";s:27:\"enhanced_ecommerce_tracking\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:207:\"Enable enhanced ecommerce tracking in Google Analytics to collect detailed data about product views, add-to-carts, purchases, and other ecommerce activities. Requires ecommerce functionality on your website.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:22;s:5:\"class\";s:66:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Analytics\\AdvancedAnalytics\";}i:11;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:18:\"competitorAnalysis\";s:5:\"title\";s:23:\"Competitor SEO Analysis\";s:11:\"description\";s:256:\"Analyzes competitor websites to provide insights into their SEO strategies, including keyword rankings, backlink profiles, content performance, and other key metrics. Helps identify opportunities to improve your own SEO strategy and outperform competitors.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:19:\"competitor_websites\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:0:{}s:11:\"description\";s:133:\"A list of competitor website URLs to track (e.g., [\'https://competitor1.com\', \'https://competitor2.com\']). Separate URLs with commas.\";}i:1;a:4:{s:3:\"key\";s:18:\"analysis_frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:78:\"How often to perform competitor analysis: \'weekly\', \'bi-weekly\', or \'monthly\'.\";}i:2;a:4:{s:3:\"key\";s:14:\"focus_keywords\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:0:{}s:11:\"description\";s:167:\"A list of focus keywords to analyze competitor performance against (e.g., [\'SEO\', \'WordPress\']).  Leave blank to use the target keywords from the Keyword Rank Tracker.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:21;s:5:\"class\";s:63:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Tools\\CompetitorAnalysis\";}i:12;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:8:\"seoAudit\";s:5:\"title\";s:14:\"SEO Audit Tool\";s:11:\"description\";s:247:\"Performs comprehensive SEO audits, analyzing various aspects of website performance, including technical SEO, content quality, meta tags, page speed, and more. Provides actionable recommendations for site improvement and tracks progress over time.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:15:\"audit_frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:7:\"monthly\";s:11:\"description\";s:82:\"How often automated SEO audits are performed: \'weekly\', \'monthly\', or \'quarterly\'.\";}i:1;a:4:{s:3:\"key\";s:21:\"include_technical_seo\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:116:\"Include technical SEO checks in the audit, such as sitemap presence, robots.txt validation, and HTTPS configuration.\";}i:2;a:4:{s:3:\"key\";s:19:\"email_notifications\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:85:\"Send email notifications to the administrator with a summary of the SEO audit report.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:20;s:5:\"class\";s:53:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Tools\\SEOAudit\";}i:13;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:23:\"internalLinkSuggestions\";s:5:\"title\";s:29:\"Internal Link Suggestion Tool\";s:11:\"description\";s:227:\"Suggests relevant internal links based on content analysis, helping improve website SEO, site structure, and user navigation. Provides suggestions within the content editor and allows for customization of suggestion parameters.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:21:\"automatic_suggestions\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:136:\"Enable automatic internal link suggestions within the content editor. When enabled, suggestions will appear as you type or edit content.\";}i:1;a:4:{s:3:\"key\";s:14:\"min_word_count\";s:4:\"type\";s:7:\"integer\";s:7:\"default\";i:300;s:11:\"description\";s:145:\"The minimum word count for a post or page before internal link suggestions are generated.  This helps prevent suggestions for very short content.\";}i:2;a:4:{s:3:\"key\";s:15:\"max_suggestions\";s:4:\"type\";s:7:\"integer\";s:7:\"default\";i:3;s:11:\"description\";s:120:\"Maximum number of internal link suggestions to display per post/page. Prevents overwhelming users with too many options.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:19;s:5:\"class\";s:68:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Links\\InternalLinkSuggestions\";}i:14;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:18:\"keywordRankTracker\";s:5:\"title\";s:20:\"Keyword Rank Tracker\";s:11:\"description\";s:198:\"Tracks the ranking performance of specified keywords in major search engines (Google, Bing) over time. Provides reports and visualizations to monitor keyword progress and identify SEO opportunities.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:15:\"target_keywords\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:0:{}s:11:\"description\";s:194:\"A list of target keywords to track (e.g., [\'SEO\', \'WordPress\', \'content marketing\']).  These keywords should align with your website\'s content and target audience. Separate keywords with commas.\";}i:1;a:4:{s:3:\"key\";s:16:\"update_frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:80:\"How often to check and update keyword rankings: \'daily\', \'weekly\', or \'monthly\'.\";}i:2;a:4:{s:3:\"key\";s:13:\"search_engine\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"google\";s:11:\"description\";s:84:\"The primary search engine to track keyword rankings in: \'google\', \'bing\', or \'both\'.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:18;s:5:\"class\";s:66:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Keywords\\KeywordRankTracker\";}i:15;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:16:\"contentScheduler\";s:5:\"title\";s:24:\"Content Update Scheduler\";s:11:\"description\";s:220:\"Allows users to schedule content updates and revisions, helping maintain content freshness and improve SEO performance over time. Integrates with the Content Analysis module to track the impact of updates on SEO metrics.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:24:\"enable_scheduled_updates\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:109:\"Enable the content scheduling feature. When enabled, you can schedule updates for individual posts and pages.\";}i:1;a:4:{s:3:\"key\";s:23:\"default_update_interval\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:103:\"The default time interval between scheduled content updates: \'daily\', \'weekly\', \'monthly\', or \'yearly\'.\";}i:2;a:4:{s:3:\"key\";s:21:\"send_update_reminders\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:89:\"Send email reminders to content authors or administrators when a scheduled update is due.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:17;s:5:\"class\";s:63:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Content\\ContentScheduler\";}i:16;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:11:\"localSeoGmb\";s:5:\"title\";s:55:\"Local SEO Enhancements (Google My Business Integration)\";s:11:\"description\";s:125:\"Connect and manage your Google My Business profile directly from your WordPress dashboard to enhance your local SEO presence.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:2:{i:0;a:4:{s:3:\"key\";s:11:\"gmb_api_key\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:62:\"Enter your Google My Business API key to connect your account.\";}i:1;a:4:{s:3:\"key\";s:15:\"gmb_location_id\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:42:\"Enter your Google My Business location ID.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:16;s:5:\"class\";s:65:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Local\\LocalSEOEnhancements\";}i:17;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:17:\"localSeoOptimizer\";s:5:\"title\";s:19:\"Local SEO Optimizer\";s:11:\"description\";s:219:\"Optimizes websites for local search visibility by adding LocalBusiness schema markup, managing location-based keywords, and integrating with location-based services. Helps businesses rank higher in local search results.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:28:\"enable_local_business_schema\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:167:\"Enable LocalBusiness schema markup to provide search engines with detailed information about your business, including name, address, phone number, and operating hours.\";}i:1;a:4:{s:3:\"key\";s:13:\"business_name\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:118:\"The name of your local business. This should match the name used on your Google My Business profile (if you have one).\";}i:2;a:4:{s:3:\"key\";s:16:\"business_address\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:50:\"The full street address of your business location.\";}i:3;a:4:{s:3:\"key\";s:14:\"business_phone\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:0:\"\";s:11:\"description\";s:43:\"The primary phone number for your business.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:16;s:5:\"class\";s:62:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Local\\LocalSEOOptimizer\";}i:18;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:17:\"international_seo\";s:5:\"title\";s:33:\"International SEO (Hreflang Tags)\";s:11:\"description\";s:160:\"Manage hreflang tags and other locale-specific settings to optimize your website for international audiences and improve search visibility in different regions.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:2:{i:0;a:4:{s:3:\"key\";s:16:\"default_language\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:2:\"en\";s:11:\"description\";s:67:\"Set the default language for your website (e.g., \"en\", \"es\", \"fr\").\";}i:1;a:4:{s:3:\"key\";s:19:\"supported_languages\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:0:{}s:11:\"description\";s:188:\"Add an array of supported languages and their corresponding URLs (e.g., [[\"language\" => \"es\", \"url\" => \"https://example.com/es\"], [\"language\" => \"fr\", \"url\" => \"https://example.com/fr\"]]).\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:15;s:5:\"class\";s:71:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Schema\\HreflangTagsInternational\";}i:19;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:15:\"redirectManager\";s:5:\"title\";s:16:\"Redirect Manager\";s:11:\"description\";s:244:\"Manages 301 and 302 redirects to prevent broken links, preserve SEO value, and improve user experience. Allows for creating, editing, and importing/exporting redirects. Integrates with the Broken Link Checker for automated redirect suggestions.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:2:{i:0;a:4:{s:3:\"key\";s:21:\"default_redirect_type\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:3:\"301\";s:11:\"description\";s:73:\"The default redirect type to use: \'301\' (permanent) or \'302\' (temporary).\";}i:1;a:4:{s:3:\"key\";s:26:\"auto_redirect_broken_links\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:185:\"Automatically create redirects for broken links detected by the Broken Link Checker, using the most likely destination URL based on content similarity or historical data (if available).\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:15;s:5:\"class\";s:76:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Links\\RedirectManager\\RedirectManager\";}i:20;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:17:\"brokenLinkChecker\";s:5:\"title\";s:19:\"Broken Link Checker\";s:11:\"description\";s:183:\"Regularly scans the website for broken links (internal and external) and notifies the administrator. Helps maintain site health and improve SEO by identifying and fixing broken links.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:12:\"notify_admin\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:77:\"Send email notifications to the administrator when broken links are detected.\";}i:1;a:4:{s:3:\"key\";s:15:\"check_frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:69:\"How often to check for broken links: \'daily\', \'weekly\', or \'monthly\'.\";}i:2;a:4:{s:3:\"key\";s:21:\"broken_link_threshold\";s:4:\"type\";s:7:\"integer\";s:7:\"default\";i:5;s:11:\"description\";s:146:\"The minimum number of broken links that must be detected before sending a notification. This helps prevent notification overload for minor issues.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:14;s:5:\"class\";s:62:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Links\\BrokenLinkChecker\";}i:21;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:15:\"contentAnalysis\";s:5:\"title\";s:20:\"SEO Content Analysis\";s:11:\"description\";s:211:\"Performs in-depth analysis of content to assess SEO performance, focusing on keyword density, readability, content length, and other relevant factors. Provides actionable recommendations for content improvement.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:21:\"check_keyword_density\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:83:\"Analyze keyword density to ensure optimal keyword usage and avoid keyword stuffing.\";}i:1;a:4:{s:3:\"key\";s:17:\"check_readability\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:105:\"Analyze content readability to assess its complexity and suggest improvements for better user engagement.\";}i:2;a:4:{s:3:\"key\";s:18:\"min_content_length\";s:4:\"type\";s:7:\"integer\";s:7:\"default\";i:300;s:11:\"description\";s:107:\"Minimum recommended content length (in words).  Content shorter than this might be flagged for improvement.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:13;s:5:\"class\";s:78:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Content\\ContentAnalysis\\ContentAnalysis\";}i:22;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:12:\"schemaMarkup\";s:5:\"title\";s:22:\"Structured Data Markup\";s:11:\"description\";s:229:\"Adds structured data markup (using schema.org vocabulary) to pages and posts, enhancing SEO visibility by providing search engines with more context about the content. Supports various schema types, configurable through settings.\";s:7:\"version\";s:5:\"1.2.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:21:\"enable_article_schema\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:130:\"Enable schema markup for articles and blog posts, providing information about author, publishing date, and other relevant details.\";}i:1;a:4:{s:3:\"key\";s:21:\"enable_product_schema\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:96:\"Enable schema markup for product pages, including details like price, availability, and reviews.\";}i:2;a:4:{s:3:\"key\";s:19:\"default_schema_type\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:7:\"Article\";s:11:\"description\";s:162:\"The default schema type to use for pages that don\'t have a specific schema type assigned. Options: \'Article\', \'WebPage\', etc. (See documentation for a full list).\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:12;s:5:\"class\";s:71:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Schema\\SchemaMarkup\\SchemaMarkup\";}i:23;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:21:\"serp_feature_tracking\";s:5:\"title\";s:21:\"SERP Feature Tracking\";s:11:\"description\";s:149:\"Track your website\'s performance in SERP features (featured snippets, knowledge panels, etc.) to optimize your content and improve search visibility.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:2:{i:0;a:4:{s:3:\"key\";s:15:\"target_keywords\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:0:{}s:11:\"description\";s:90:\"Enter an array of target keywords to track for SERP features (e.g., [\'SEO\', \'WordPress\']).\";}i:1;a:4:{s:3:\"key\";s:20:\"target_search_engine\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"google\";s:11:\"description\";s:83:\"Select the target search engine for SERP feature tracking (e.g., \"google\", \"bing\").\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:12;s:5:\"class\";s:67:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Keywords\\SERPFeatureTracking\";}i:24;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:27:\"content_duplication_checker\";s:5:\"title\";s:27:\"Content Duplication Checker\";s:11:\"description\";s:131:\"Identifies and helps resolve duplicate content issues within your website and optionally across the web to improve SEO performance.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:25:\"check_internal_duplicates\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:52:\"Check for duplicate content within your own website.\";}i:1;a:4:{s:3:\"key\";s:25:\"check_external_duplicates\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:77:\"Check for duplicate content across the web (may require an external service).\";}i:2;a:4:{s:3:\"key\";s:17:\"sensitivity_level\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"medium\";s:11:\"description\";s:90:\"Set the sensitivity level for duplicate content detection (e.g., \"low\", \"medium\", \"high\").\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:11;s:5:\"class\";s:72:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Content\\ContentDuplicationChecker\";}i:25;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:13:\"customSidebar\";s:5:\"title\";s:11:\"SEO Sidebar\";s:11:\"description\";s:69:\"Adds a SEO sidebar to the WordPress editor for managing SEO metadata.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:0:{}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:10;s:5:\"class\";s:76:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Technical\\CustomSidebar\\CustomSidebar\";}i:26;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:21:\"keyword_research_tool\";s:5:\"title\";s:21:\"Keyword Research Tool\";s:11:\"description\";s:174:\"Discover new keyword opportunities with integrated keyword research functionality. Analyze search volume, competition, and related keywords to optimize your content strategy.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:23:\"preferred_search_engine\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"google\";s:11:\"description\";s:82:\"Select your preferred search engine for keyword research (e.g., \"google\", \"bing\").\";}i:1;a:4:{s:3:\"key\";s:12:\"country_code\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:2:\"us\";s:11:\"description\";s:88:\"Specify the target country code for localized keyword research (e.g., \"us\", \"uk\", \"de\").\";}i:2;a:4:{s:3:\"key\";s:13:\"language_code\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:2:\"en\";s:11:\"description\";s:79:\"Specify the target language code for keyword research (e.g., \"en\", \"es\", \"fr\").\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:10;s:5:\"class\";s:67:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Keywords\\KeywordResearchTool\";}i:27;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:7:\"sitemap\";s:5:\"title\";s:21:\"XML Sitemap Generator\";s:11:\"description\";s:187:\"Generates and submits XML sitemaps to search engines (Google, Bing, etc.) to improve indexation and SEO visibility.  Includes options for customizing sitemap content and update frequency.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:14:\"include_images\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:65:\"Include images in the sitemap to improve image search visibility.\";}i:1;a:4:{s:3:\"key\";s:9:\"frequency\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:6:\"weekly\";s:11:\"description\";s:80:\"How often the sitemap is regenerated: \'daily\', \'weekly\', \'monthly\', or \'yearly\'.\";}i:2;a:4:{s:3:\"key\";s:18:\"include_post_types\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:2:{i:0;s:4:\"post\";i:1;s:4:\"page\";}s:11:\"description\";s:95:\"An array of WordPress post types to include in the sitemap (e.g., [\'post\', \'page\', \'product\']).\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:8;s:5:\"class\";s:56:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Technical\\Sitemap\";}i:28;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:9:\"pageSpeed\";s:5:\"title\";s:20:\"Page Speed Optimizer\";s:11:\"description\";s:191:\"Analyzes and improves page speed through various optimization techniques, such as image lazy loading, JavaScript/CSS minification, and caching, to enhance SEO performance and user experience.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:19:\"enable_lazy_loading\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:131:\"Enable lazy loading for images. Images will only be loaded when they are visible in the viewport, improving initial page load time.\";}i:1;a:4:{s:3:\"key\";s:13:\"minify_js_css\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:132:\"Minify JavaScript and CSS files to reduce their size and improve download speed. This removes unnecessary characters and whitespace.\";}i:2;a:4:{s:3:\"key\";s:22:\"enable_browser_caching\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:148:\"Enable browser caching to store static assets (images, CSS, JS) locally on the user\'s browser, reducing the number of requests on subsequent visits.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:7;s:5:\"class\";s:60:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Performance\\PageSpeed\";}i:29;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:19:\"mobile_seo_analyzer\";s:5:\"title\";s:19:\"Mobile SEO Analyzer\";s:11:\"description\";s:197:\"Comprehensive mobile SEO analysis and optimization toolkit that ensures your website meets mobile-first indexing requirements, optimizes mobile user experience, and improves mobile search rankings.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:21:\"mobile_viewport_check\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:95:\"Automatically check and validate mobile viewport configurations and responsive design elements.\";}i:1;a:4:{s:3:\"key\";s:21:\"touch_element_spacing\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:71:\"Analyze and optimize touch element spacing for better mobile usability.\";}i:2;a:4:{s:3:\"key\";s:23:\"mobile_speed_monitoring\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:69:\"Monitor and optimize mobile page load speeds and performance metrics.\";}i:3;a:4:{s:3:\"key\";s:23:\"amp_compatibility_check\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:49:\"Check and validate AMP implementation if enabled.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:6;s:5:\"class\";s:66:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Technical\\MobileSEOAnalyser\";}i:30;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:23:\"ecommerce_seo_optimizer\";s:5:\"title\";s:24:\"E-commerce SEO Optimizer\";s:11:\"description\";s:181:\"Specialized SEO optimization suite for e-commerce websites, focusing on product pages, category optimization, and shopping feed management to improve visibility in product searches.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:25:\"product_schema_automation\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:75:\"Automatically generate and optimize product schema markup for all products.\";}i:1;a:4:{s:3:\"key\";s:26:\"category_page_optimization\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:82:\"Optimize category pages with appropriate meta data and internal linking structure.\";}i:2;a:4:{s:3:\"key\";s:25:\"review_markup_integration\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:63:\"Integrate product reviews into schema markup for rich snippets.\";}i:3;a:4:{s:3:\"key\";s:26:\"shopping_feed_optimization\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:72:\"Optimize product feeds for Google Shopping and other shopping platforms.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:5;s:5:\"class\";s:66:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Store\\EcommerceSEOOptimizer\";}i:31;a:9:{s:6:\"active\";b:1;s:4:\"name\";s:8:\"metaTags\";s:5:\"title\";s:17:\"Meta Tags Manager\";s:11:\"description\";s:236:\"Manages and optimizes meta tags (title, description, keywords, viewport, Open Graph, etc.) for individual pages and posts to improve SEO, responsive design, and social media sharing. Provides default values and allows for customization.\";s:7:\"version\";s:5:\"1.2.0\";s:8:\"settings\";a:5:{i:0;a:4:{s:3:\"key\";s:19:\"default_description\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:20:\"Welcome to our site!\";s:11:\"description\";s:146:\"The default meta description used for pages and posts that do not have a custom description set.  This description should be concise and enticing.\";}i:1;a:4:{s:3:\"key\";s:16:\"default_keywords\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:20:\"WordPress, SEO, blog\";s:11:\"description\";s:113:\"Default meta keywords. While less impactful than descriptions, these can still provide context to search engines.\";}i:2;a:4:{s:3:\"key\";s:15:\"og_image_source\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:14:\"featured_image\";s:11:\"description\";s:75:\"Source for the Open Graph image: \'featured_image\', \'custom_url\', or \'none\'.\";}i:3;a:4:{s:3:\"key\";s:16:\"default_viewport\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:37:\"width=device-width, initial-scale=1.0\";s:11:\"description\";s:110:\"Default viewport meta tag content for responsive design. Controls how the page is displayed on mobile devices.\";}i:4;a:4:{s:3:\"key\";s:15:\"enable_viewport\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:81:\"Enable automatic viewport meta tag generation for responsive design optimization.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:5;s:5:\"class\";s:66:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Technical\\MetaTags\\MetaTags\";}i:32;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:23:\"core_web_vitals_monitor\";s:5:\"title\";s:23:\"Core Web Vitals Monitor\";s:11:\"description\";s:193:\"Real-time monitoring and optimization system for Core Web Vitals metrics (LCP, FID, CLS), providing actionable insights and automatic optimization suggestions to improve search ranking signals.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:4:{i:0;a:4:{s:3:\"key\";s:20:\"real_time_monitoring\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:55:\"Enable real-time monitoring of Core Web Vitals metrics.\";}i:1;a:4:{s:3:\"key\";s:18:\"performance_alerts\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:74:\"Send alerts when Core Web Vitals metrics fall below acceptable thresholds.\";}i:2;a:4:{s:3:\"key\";s:22:\"automatic_optimization\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:60:\"Automatically apply recommended optimizations when possible.\";}i:3;a:4:{s:3:\"key\";s:19:\"field_data_analysis\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:63:\"Analyze real user metrics data for Core Web Vitals performance.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:4;s:5:\"class\";s:69:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Analytics\\CoreWebVitalsMonitor\";}i:33;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:13:\"textOptimizer\";s:5:\"title\";s:17:\"Content Optimizer\";s:11:\"description\";s:188:\"Analyzes and optimizes content for SEO by evaluating keyword density, readability, and other relevant factors. Provides suggestions for improving content quality and search engine ranking.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:15:\"target_keywords\";s:4:\"type\";s:5:\"array\";s:7:\"default\";a:0:{}s:11:\"description\";s:145:\"An array of primary keywords to target for content optimization (e.g., [\'SEO\', \'WordPress\', \'content marketing\']). Separate keywords with commas.\";}i:1;a:4:{s:3:\"key\";s:27:\"enable_readability_analysis\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:109:\"Enable readability analysis to assess content complexity and suggest improvements for better user engagement.\";}i:2;a:4:{s:3:\"key\";s:14:\"min_word_count\";s:4:\"type\";s:7:\"integer\";s:7:\"default\";i:300;s:11:\"description\";s:130:\"Minimum word count for content analysis to be performed.  Shorter content might not provide sufficient data for accurate analysis.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:4;s:5:\"class\";s:60:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Content\\TextOptimizer\";}i:34;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:14:\"imageOptimizer\";s:5:\"title\";s:15:\"Image Optimizer\";s:11:\"description\";s:173:\"Optimizes images upon upload or manually to reduce file sizes, improve page load speed, and enhance SEO.  Uses various optimization techniques configurable through settings.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:18:\"optimize_on_upload\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:74:\"Automatically optimize images when they are uploaded to the media library.\";}i:1;a:4:{s:3:\"key\";s:17:\"compression_level\";s:4:\"type\";s:7:\"integer\";s:7:\"default\";i:75;s:11:\"description\";s:94:\"Sets the compression level for image optimization (0-100, where 100 is the least compression).\";}i:2;a:4:{s:3:\"key\";s:19:\"optimization_method\";s:4:\"type\";s:6:\"string\";s:7:\"default\";s:5:\"lossy\";s:11:\"description\";s:132:\"Choose the image optimization method: \'lossy\' for smaller file sizes (some quality loss) or \'lossless\' for preserving image quality.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:2;s:5:\"class\";s:59:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\Media\\ImageOptimizer\";}i:35;a:9:{s:6:\"active\";b:0;s:4:\"name\";s:29:\"specializedPluginIntegrations\";s:5:\"title\";s:31:\"Specialized Plugin Integrations\";s:11:\"description\";s:135:\"Provides tailored integrations with specific, popular non-SEO plugins to enhance their functionalities with SEO data and optimizations.\";s:7:\"version\";s:5:\"1.0.0\";s:8:\"settings\";a:3:{i:0;a:4:{s:3:\"key\";s:31:\"woocommerce_integration_enabled\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:1;s:11:\"description\";s:36:\"Enable integration with WooCommerce.\";}i:1;a:4:{s:3:\"key\";s:34:\"contact_form_7_integration_enabled\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:39:\"Enable integration with Contact Form 7.\";}i:2;a:4:{s:3:\"key\";s:29:\"elementor_integration_enabled\";s:4:\"type\";s:7:\"boolean\";s:7:\"default\";b:0;s:11:\"description\";s:34:\"Enable integration with Elementor.\";}}s:12:\"dependencies\";a:0:{}s:8:\"priority\";i:2;s:5:\"class\";s:78:\"RankingCoach\\Inc\\Modules\\ModuleLibrary\\WordPress\\SpecializedPluginIntegrations\";}}}', 'off'),
