INSERT INTO `oamy_rankingcoach_setup_questions` (`id`, `stepId`, `question`, `sequence`, `aiContext`, `parentId`, `isAiGenerated`) VALUES
(1, 1, 'Let\'s get started.', 1, NULL, NULL, 0),
(2, 1, 'First, could you tell me what your website or project is about?', 2, NULL, NULL, 0),
(3, 2, 'Awesome!', 1, NULL, NULL, 0),
(4, 2, 'Do you already have a name for your website, project, or business?', 2, NULL, NULL, 0),
(5, 3, 'Wonderful!', 1, NULL, NULL, 0),
(6, 3, 'Could you describe in more detail what you plan to do with your website? For example, will you offer products or services, share blog articles, or something else?', 2, NULL, NULL, 0),
(7, 4, 'Just tasty! Thanks for sharing!', 1, NULL, NULL, 0),
(8, 4, 'Is your project or business tied to a specific location? Do you serve customers locally, or operate in multiple areas?', 2, NULL, NULL, 0),
(9, 5, 'I see.', 1, NULL, NULL, 0),
(10, 5, 'Where do you primarily want to focus your reach? Is there a particular city or region you\'d like to target, or do you want to go nationwide?', 2, NULL, NULL, 0),
(11, 6, 'Thanks for providing that!', 1, NULL, NULL, 0),
(12, 6, 'Lastly, is there anything else you\'d like to highlight about your project or business, something that makes it unique or special?', 2, NULL, NULL, 0);
